DELIMITER $$
--
-- Funciones
--
CREATE DEFINER=`u670881161_appasis`@`127.0.0.1` FUNCTION `calcular_distancia_metros` (`lat1` DECIMAL(10,8), `lng1` DECIMAL(11,8), `lat2` DECIMAL(10,8), `lng2` DECIMAL(11,8)) RETURNS INT DETERMINISTIC READS SQL DATA BEGIN
    DECLARE resultado INT DEFAULT 0;

    IF lat1 IS NULL OR lng1 IS NULL OR lat2 IS NULL OR lng2 IS NULL THEN
        RETURN NULL;
    END IF;

    IF lat1 < -90 OR lat1 > 90 OR lng1 < -180 OR lng1 > 180 THEN
        RETURN NULL;
    END IF;

    IF lat2 < -90 OR lat2 > 90 OR lng2 < -180 OR lng2 > 180 THEN
        RETURN NULL;
    END IF;

    
    SET resultado = CAST(
        6371000 * ACOS(
            LEAST(1, GREATEST(-1,
                COS(RADIANS(lat1)) * COS(RADIANS(lat2)) * COS(RADIANS(lng2) - RADIANS(lng1))
                + SIN(RADIANS(lat1)) * SIN(RADIANS(lat2))
            ))
        ) AS SIGNED
    );

    RETURN resultado;
END$$

DELIMITER ;

