CREATE ALGORITHM=UNDEFINED DEFINER=`u670881161_appasis`@`127.0.0.1` SQL SECURITY INVOKER VIEW `vw_asistencia_con_distancia`  AS SELECT `ra`.`id_registro` AS `id_registro`, `ra`.`id_usuario` AS `id_usuario`, `ra`.`id_sede` AS `id_sede`, `ra`.`id_jornada` AS `id_jornada`, `ra`.`tipo` AS `tipo`, `ra`.`foto_url` AS `foto_url`, `ra`.`latitud` AS `latitud`, `ra`.`longitud` AS `longitud`, `ra`.`hora_local` AS `hora_local`, `ra`.`hora_servidor_utc` AS `hora_servidor_utc`, `s`.`nombre` AS `sede_nombre`, `s`.`latitud` AS `sede_latitud`, `s`.`longitud` AS `sede_longitud`, `s`.`radio_geocerca_metros` AS `radio_geocerca_metros`, (6371000 * acos(least(1,greatest(-(1),(((cos(radians(`s`.`latitud`)) * cos(radians(`ra`.`latitud`))) * cos((radians(`ra`.`longitud`) - radians(`s`.`longitud`)))) + (sin(radians(`s`.`latitud`)) * sin(radians(`ra`.`latitud`)))))))) AS `distancia_metros`, `ra`.`dentro_geocerca` AS `dentro_geocerca`, `ra`.`dentro_horario` AS `dentro_horario` FROM (`registros_asistencia` `ra` join `sedes` `s` on((`s`.`id_sede` = `ra`.`id_sede`))) ;

